@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

:root {
  --background: oklch(0.99 0 0);
  --foreground: oklch(0.13 0 0);

  --card: oklch(0.98 0 0);
  --card-foreground: oklch(0.13 0 0);

  --popover: oklch(0.99 0 0);
  --popover-foreground: oklch(0.13 0 0);

  --primary: oklch(0.13 0 0);
  --primary-foreground: oklch(0.99 0 0);

  --secondary: oklch(0.96 0 0);
  --secondary-foreground: oklch(0.35 0 0);

  --muted: oklch(0.96 0 0);
  --muted-foreground: oklch(0.55 0 0);

  --accent: oklch(0.96 0 0);
  --accent-foreground: oklch(0.13 0 0);

  --destructive: oklch(0.58 0.22 27);
  --destructive-foreground: oklch(0.99 0 0);

  --border: oklch(0.91 0 0);
  --input: oklch(0.91 0 0);
  --ring: oklch(0.13 0 0);
  --radius: 0.375rem;

  --neutral-50: oklch(0.985 0 0);
  --neutral-100: oklch(0.96 0 0);
  --neutral-200: oklch(0.91 0 0);
  --neutral-300: oklch(0.85 0 0);
  --neutral-400: oklch(0.65 0 0);
  --neutral-500: oklch(0.55 0 0);
  --neutral-600: oklch(0.45 0 0);
  --neutral-700: oklch(0.35 0 0);
  --neutral-800: oklch(0.2 0 0);
  --neutral-900: oklch(0.13 0 0);
}

.dark {
  --background: oklch(0.13 0 0);
  --foreground: oklch(0.96 0 0);

  --card: oklch(0.17 0 0);
  --card-foreground: oklch(0.96 0 0);

  --popover: oklch(0.15 0 0);
  --popover-foreground: oklch(0.96 0 0);

  --primary: oklch(0.96 0 0);
  --primary-foreground: oklch(0.13 0 0);

  --secondary: oklch(0.2 0 0);
  --secondary-foreground: oklch(0.65 0 0);

  --muted: oklch(0.2 0 0);
  --muted-foreground: oklch(0.55 0 0);

  --accent: oklch(0.2 0 0);
  --accent-foreground: oklch(0.96 0 0);

  --destructive: oklch(0.58 0.22 27);
  --destructive-foreground: oklch(0.99 0 0);

  --border: oklch(0.25 0 0);
  --input: oklch(0.2 0 0);
  --ring: oklch(0.96 0 0);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 2px);
  --radius-md: var(--radius);
  --radius-lg: calc(var(--radius) + 2px);
  --radius-xl: calc(var(--radius) + 6px);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  /* Tactile Minimal uses the OS system font stack — no Geist, no custom display font.
     This matches the source site: clean, understated, system-native feel. */
  [data-ds="tactile-minimal"],
  [data-ds="tactile-minimal"] * {
    font-family:
      ui-sans-serif,
      system-ui,
      -apple-system,
      BlinkMacSystemFont,
      "Segoe UI",
      Roboto,
      "Helvetica Neue",
      Arial,
      sans-serif;
    font-feature-settings: "ss01", "cv11";
  }
  /* Override the showcase's inline h1 style (28px/700) so the page header
     matches the design system's understated typography. */
  [data-ds="tactile-minimal"] h1 {
    font-size: 14px !important;
    font-weight: 600 !important;
    letter-spacing: -0.005em !important;
  }
  html {
    font-family:
      var(--font-geist-sans),
      ui-sans-serif,
      system-ui,
      -apple-system,
      BlinkMacSystemFont,
      "Segoe UI",
      Roboto,
      "Helvetica Neue",
      Arial,
      sans-serif;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }
}
